@@ -407,3 +407,49 @@ test("direction-aware defaults", () => {
     }
   `);
 });
+
+test("default factory runs once per parse inside a container", () => {
+  let calls = 0;
+  const schema = z.object({
+    a: z.string().default(() => {
+      calls++;
+      return "d";
+    }),
+  });
+
+  expect(schema.parse({})).toEqual({ a: "d" });
+  expect(calls).toBe(1);
+
+  // the key is present, so the factory has nothing to produce
+  expect(schema.parse({ a: "given" })).toEqual({ a: "given" });
+  expect(calls).toBe(1);
+});
+
+test("prefault factory runs once per parse inside a container", () => {
+  let calls = 0;
+  const schema = z.object({
+    a: z.string().prefault(() => {
+      calls++;
+      return "d";
+    }),
+  });
+
+  expect(schema.parse({})).toEqual({ a: "d" });
+  expect(calls).toBe(1);
+});
+
+test("default factory does not run at compile time", () => {
+  let calls = 0;
+  const compiled = z.compile(
+    z.object({
+      a: z.string().default(() => {
+        calls++;
+        return "d";
+      }),
+    })
+  );
+
+  expect(calls).toBe(0);
+  expect(compiled.parse({})).toEqual({ a: "d" });
+  expect(calls).toBe(1);
+});

problem_statement:
Functions are executed twice for object property defaults

If you define an object type and use a function for a property's default value, the function is executed twice:
```js
let test = 0;
const schema = z.object({

    TEST: z.string().default(() => {
        console.log(`Executed... ${test++}`);
        return 'default';
    })

})

schema.parse({});
// Executed... 0
// Executed... 1
```

When it's not wrapped in an object, the function is only executed once, as expected:
```js
const defaultTuna = z.string().default(() => {
    console.log(`tuna`);
    return 'tuna';
});

defaultTuna.parse(undefined); // => "tuna"
```

I'm currently using Node.js v24.14.1 and Zod v4.5.2. 
I have not checked the versions in between, but Zod v4.4.2 does not have this issue and the default function is only executed once.
